using System;
using System.Linq;
using NUnit.Framework;
using UnityEngine;
namespace YesterdayConvoy.Editor.Tests
{
    public sealed class BossRosterCombatTests
    {
        static ManualBattle Battle(string task,out DeployedUnitState unit,string variant="TL-10",float guardHealth=10000,bool begin=true,bool guardsAttack=false)
        {
            Assert.That(BossRosterCatalog.TryGet("CARD_"+task,out var e),Is.True);
            var settings=new ManualBattleSettings(e.CardId,e.UnitId,100,5,3,1,.2f,e.Health,e.Speed,1,30,1,10000);
            var combat=new EngagementSettings(unitAttack:e.Attack,unitArmor:e.Armor,unitRange:e.Range,unitInterval:e.Interval,defenderHealth:guardHealth,defenderAttack:.01f,defenderArmor:0,defenderRange:3,defenderInterval:10000,initialSP:1,requiredSP:2,spPerSecond:1,skillAmmo:1,skillAttack:e.Attack,skillInterval:Math.Max(1,e.AttackDuration),skillRange:3,projectileTime:.1f,attackDuration:e.AttackDuration,attackWindup:e.Windup,canAttack:task!="B10"&&task!="B21");
            var guards=new[]{new DefenderSettings("near","近身",null,new Vector3(.6f,0,0),guardHealth,.01f,0,3,guardsAttack?1:10000,1,canAttack:guardsAttack),new DefenderSettings("rear","后排",null,new Vector3(1.8f,0,.3f),guardHealth,.01f,0,3,guardsAttack?1:10000,0,canAttack:guardsAttack),new DefenderSettings("far","远端",null,new Vector3(3,0,.1f),guardHealth,.01f,0,3,guardsAttack?1:10000,0,canAttack:guardsAttack)};
            var battle=new ManualBattle(settings,new[]{Vector3.zero,new Vector3(20,0,0)},new Vector3(8,0,0),combat,roster:guards);battle.ConfigureBossRosterSourceVariant(variant);unit=null;if(!begin)return battle;battle.Begin();var receipt=battle.TryDeploy(battle.RunId,1,battle.Entry);Assert.That(receipt.Success,Is.True);unit=battle.FindUnit(receipt.EntityId);return battle;
        }
        static void Charge(ManualBattle b,DeployedUnitState u,string id){var state=b.BossRoster(u);var info=b.BossRosterSkills(u).Single(x=>x.SkillId==id);state.SP[id]=info.MaxSP;}
        [TestCase("B01")][TestCase("B03")][TestCase("B04")][TestCase("B05")][TestCase("B07")][TestCase("B08")][TestCase("B09")][TestCase("B10")][TestCase("B11")][TestCase("B12")][TestCase("B13")][TestCase("B14")][TestCase("B15")][TestCase("B21")][TestCase("B22")][TestCase("B23")][TestCase("B24")][TestCase("B25")][TestCase("B26")]
        public void EveryNewCardDeploysAndOwnsIndependentClockedSkillState(string task)
        {
            var b=Battle(task,out var u);Assert.That(b.BossRoster(u),Is.Not.Null);Assert.That(b.BossRosterSkills(u).Count,Is.GreaterThan(0));var state=b.BossRoster(u);var initial=b.BossRosterSkills(u).ToArray();if(task=="B11"){Assert.That(initial.Any(x=>x.SkillId=="annihilation"),Is.False);Assert.That(b.TryActivateBossRosterSkill(b.RunId,999,u.EntityId,"annihilation"),Is.EqualTo(SkillFailure.NoSkill),"The source map timeout script is not a recruitable manual ability.");}if(task=="B21"){Assert.That(initial.Any(x=>x.SkillId=="mountains"),Is.False);Assert.That(b.TryActivateBossRosterSkill(b.RunId,1000,u.EntityId,"mountains"),Is.EqualTo(SkillFailure.NoSkill),"The three automatic follow-up strikes cannot be manually duplicated.");}b.Advance(.3f);b.SetPaused(true);double clock=b.Clock;float hp=u.Health;var resources=b.BossRosterSkills(u).Select(x=>x.SP).ToArray();b.Advance(10);Assert.That(b.Clock,Is.EqualTo(clock));Assert.That(u.Health,Is.EqualTo(hp));Assert.That(b.BossRosterSkills(u).Select(x=>x.SP).ToArray(),Is.EqualTo(resources));b.Restart();Assert.That(b.BossRosterEvents.Count,Is.EqualTo(0));Assert.That(b.BossRosterObjects.Count,Is.EqualTo(0));Assert.That(b.Units.Count,Is.EqualTo(0));
        }
        [Test]public void TwoSameBossesKeepSeparateSkillRequestsAndPerSkillSp()
        {
            var b=Battle("B04",out var first);b.Advance(2);first.Motion.Advance(2);var receipt=b.TryDeploy(b.RunId,2,b.Entry);Assert.That(receipt.Success,Is.True);var second=b.FindUnit(receipt.EntityId);Charge(b,first,"dash");Charge(b,first,"blizzard");float other=b.BossRoster(second).SP["dash"],blizzard=b.BossRoster(first).SP["blizzard"];Assert.That(b.TryActivateBossRosterSkill(b.RunId,9,first.EntityId,"dash"),Is.EqualTo(SkillFailure.None));Assert.That(b.BossRoster(first).SP["dash"],Is.Zero);Assert.That(b.BossRoster(first).SP["blizzard"],Is.EqualTo(blizzard));Assert.That(b.BossRoster(second).SP["dash"],Is.EqualTo(other));Assert.That(b.TryActivateBossRosterSkill(b.RunId,9,first.EntityId,"dash"),Is.EqualTo(SkillFailure.None));Assert.That(first.SkillsUsed,Is.EqualTo(1));Assert.That(b.TryActivateBossRosterSkill(b.RunId,9,first.EntityId,"blizzard"),Is.EqualTo(SkillFailure.StaleRun));
        }
        [Test]public void B22BothNativeHitsDealDamageAndRemainDistinct()
        {
            var b=Battle("B22",out var u);float hp=b.Defender.Health;b.Advance(1.1f);var impacts=b.BossRosterEvents.Where(e=>e.EntityId==u.EntityId&&e.Kind=="Impact"&&e.SkillKey=="attack").ToArray();Assert.That(impacts.Length,Is.EqualTo(2));Assert.That(impacts.Select(x=>x.HitIndex),Is.EqualTo(new[]{0,1}));Assert.That(impacts.All(x=>x.Applied),Is.True);Assert.That(impacts[1].At-impacts[0].At,Is.EqualTo(.2333334).Within(.051));Assert.That(b.Defender.Health,Is.LessThan(hp-b.UnitCombat(u).UnitAttack));
        }
        [Test]public void RangedNativeProjectileDealsNothingAtLaunchAndPauseFreezesRealFlight()
        {var b=Battle("B01",out var u);float hp=b.Defender.Health;for(int i=0;i<60&&!b.BossRosterEvents.Any(e=>e.Kind=="ProjectileSpawn"&&e.SkillKey=="attack");i++)b.Advance(.05f);var launch=b.BossRosterEvents.Single(e=>e.Kind=="ProjectileSpawn"&&e.SkillKey=="attack");Assert.That(launch.EndAt,Is.GreaterThan(launch.At));Assert.That(b.Defender.Health,Is.EqualTo(hp));Assert.That(b.BossRosterEvents.Any(e=>e.Kind=="Impact"&&e.ActivationId==launch.ActivationId),Is.False);b.SetPaused(true);double clock=b.Clock;b.Advance(10);Assert.That(b.Clock,Is.EqualTo(clock));Assert.That(b.Defender.Health,Is.EqualTo(hp));b.SetPaused(false);b.Advance(.5f);Assert.That(b.Defender.Health,Is.LessThan(hp));Assert.That(b.BossRosterEvents.Count(e=>e.Kind=="Impact"&&e.ActivationId==launch.ActivationId&&e.Applied),Is.EqualTo(1));}
        [Test]public void AnAlreadyLaunchedNativeProjectileSurvivesItsSourceAsItsSourceFlagSpecifies()
        {var b=Battle("B01",out var u);for(int i=0;i<60&&!b.BossRosterEvents.Any(e=>e.Kind=="ProjectileSpawn"&&e.SkillKey=="attack");i++)b.Advance(.05f);var launch=b.BossRosterEvents.Single(e=>e.Kind=="ProjectileSpawn"&&e.SkillKey=="attack");float hp=b.Defender.Health;b.TryDamageUnit(u.EntityId,u.MaxHealth*3,CombatDamageType.Physical);Assert.That(u.Resolution,Is.EqualTo(UnitResolution.Dead));b.Advance(.5f);Assert.That(b.Defender.Health,Is.LessThan(hp));Assert.That(b.BossRosterEvents.Single(e=>e.Kind=="Impact"&&e.ActivationId==launch.ActivationId).Phase,Is.EqualTo(launch.Phase));}
        [Test]public void ALaunchedProjectileStillArrivesWithoutInventingDamageAfterItsTargetDies()
        {var b=Battle("B01",out var u);for(int i=0;i<60&&!b.BossRosterEvents.Any(e=>e.Kind=="ProjectileSpawn"&&e.SkillKey=="attack");i++)b.Advance(.05f);var launch=b.BossRosterEvents.Single(e=>e.Kind=="ProjectileSpawn"&&e.SkillKey=="attack");b.Defender.Health=0;float rest=b.Defenders.Sum(d=>d.Health);b.Advance(.5f);var reached=b.BossRosterEvents.Single(e=>e.Kind=="Impact"&&e.ActivationId==launch.ActivationId);Assert.That(reached.Applied,Is.False);Assert.That(reached.Position,Is.EqualTo(launch.Position));Assert.That(reached.TargetPosition,Is.EqualTo(launch.TargetPosition));Assert.That(b.Defenders.Sum(d=>d.Health),Is.EqualTo(rest));}
        [Test]public void WDelayedC4UsesRealHealthAndPauseFreezesItsFuse()
        {
            var b=Battle("B01",out var u);Charge(b,u,"c4");Assert.That(b.TryActivateBossRosterSkill(b.RunId,3,u.EntityId,"c4"),Is.EqualTo(SkillFailure.None));b.Advance(1.5f);var installed=b.BossRosterEvents.Single(e=>e.Kind=="ProjectileSpawn"&&e.SkillKey=="c4");Assert.That(installed.At,Is.EqualTo(.6).Within(.051));Assert.That(installed.EndAt-installed.At,Is.EqualTo(3.2).Within(.001));Assert.That(b.BossRosterEvents.Any(e=>e.Kind=="Impact"&&e.SkillKey=="c4"),Is.False);b.SetPaused(true);float hp=b.Defender.Health;int n=b.BossRosterEvents.Count;b.Advance(20);Assert.That(b.Defender.Health,Is.EqualTo(hp));Assert.That(b.BossRosterEvents.Count,Is.EqualTo(n));b.SetPaused(false);b.Advance(5);Assert.That(b.BossRosterEvents.Any(e=>e.Kind=="Impact"&&e.SkillKey=="c4"&&e.Applied),Is.True);Assert.That(b.Defender.Health,Is.LessThan(hp));
        }
        [Test]public void B24RealLevelSelectionKeepsNormalHalfOnceAndSpecialThreeOrderedOneShots()
        {
            foreach(string variant in new[]{"TL-10","TL-S-4"})
            {var b=Battle("B24",out var u,variant);var s=b.BossRoster(u);s.Phase=2;Assert.That(b.TryDamageUnit(u.EntityId,u.Health*.8f+b.UnitCombat(u).UnitArmor,CombatDamageType.Physical),Is.True);b.Advance(18);var casts=b.BossRosterEvents.Where(e=>e.Kind=="SkillStart"&&e.SkillKey=="deathKnock").ToArray();Assert.That(casts.Length,Is.EqualTo(variant=="TL-10"?1:3));Assert.That(casts.Select(x=>x.NativeSkillKey),Is.EqualTo(variant=="TL-10"?new[]{"Skill2OnlyHp50"}:new[]{"Skill2Hp75","Skill2Hp50","Skill2Hp25"}));b.Advance(5);Assert.That(b.BossRosterEvents.Count(e=>e.Kind=="SkillStart"&&e.SkillKey=="deathKnock"),Is.EqualTo(casts.Length));}
        }
        [Test]public void CadejoPainAvatarsHaveRealIndependentHealthAndAllMustFall()
        {
            var b=Battle("B14",out var u);b.TryDamageUnit(u.EntityId,u.MaxHealth*3,CombatDamageType.Physical);b.Advance(4);Assert.That(b.BossRosterObjects.Count(o=>o.Kind=="pain"),Is.Zero,"A timer must not silently kill live hounds.");foreach(var hound in b.BossRosterObjects.Where(o=>o.Kind=="hound"&&o.Alive).ToArray())Assert.That(b.TryDamageBossRosterObject(b.RunId,hound.Id,hound.MaxHealth*2),Is.True);b.Advance(5.2f);var avatars=b.BossRosterObjects.Where(o=>o.Kind=="pain"&&o.Alive).ToArray();Assert.That(avatars.Length,Is.EqualTo(3));Assert.That(avatars.Select(o=>o.StartedAt).Distinct().Count(),Is.EqualTo(3));Assert.That(b.TryDamageBossRosterObject(b.RunId,avatars[0].Id,avatars[0].Health*2),Is.True);Assert.That(u.Active,Is.True);Assert.That(avatars[1].Animation,Is.EqualTo("Skill_2_Begin"));Assert.That(b.TryDamageBossRosterObject(b.RunId,avatars[1].Id,avatars[1].MaxHealth*2),Is.False);b.Advance(6);Assert.That(b.TryDamageBossRosterObject(b.RunId,avatars[1].Id,avatars[1].MaxHealth*2),Is.True);b.Advance(6);Assert.That(b.TryDamageBossRosterObject(b.RunId,avatars[2].Id,avatars[2].MaxHealth*2),Is.True);Assert.That(u.Resolution,Is.EqualTo(UnitResolution.Dead));
        }
        [Test]public void YiSecondPhaseSwitchAddsShieldAndMovingBeamsActuallyCollide()
        {
            var b=Battle("B26",out var u);var s=b.BossRoster(u);s.Phase=2;Charge(b,u,"balance");b.TryActivateBossRosterSkill(b.RunId,3,u.EntityId,"balance");b.Advance(4);Assert.That(s.Polarity,Is.EqualTo("yang"));Assert.That(s.Shield,Is.GreaterThan(0));s.LockedUntil=b.Clock;Charge(b,u,"beams");b.TryActivateBossRosterSkill(b.RunId,4,u.EntityId,"beams");b.Advance(10);Assert.That(b.BossRosterEvents.Any(e=>e.Kind=="Impact"&&e.SkillKey=="beam"&&e.Applied),Is.True);
        }
        [Test]public void ValerioOverflowIsARealCounterplayWindow()
        {
            var b=Battle("B25",out var u);var s=b.BossRoster(u);Assert.That(b.BossRosterObjects.Count(o=>o.Kind=="matrix"),Is.EqualTo(4));Assert.That(b.BossRosterSkills(u).Any(x=>x.SkillId=="absorb"||x.SkillId=="penalty"),Is.False);b.Advance(14);Assert.That(s.Matrix,Is.Zero);Assert.That(b.BossRosterObjects.Count(o=>o.Kind=="matrix"&&o.Alive),Is.Zero);Assert.That(b.BossRosterMoveLock(u),Is.True);b.SetPaused(true);double clock=b.Clock;b.Advance(50);Assert.That(b.Clock,Is.EqualTo(clock));b.SetPaused(false);b.Advance(16);Assert.That(b.BossRosterEvents.Count(e=>e.Kind=="StateEnd"&&e.SkillKey=="overload"),Is.EqualTo(1));
        }
        [Test]public void SceneObjectsKeepTheirSourceInteractionInsteadOfSharingDestructibleHp()
        {var b=Battle("B09",out var u);var camera=b.BossRosterObjects.First(o=>o.Kind=="camera");Assert.That(b.TryDamageBossRosterObject(b.RunId,camera.Id,100000),Is.False);Charge(b,u,"absurdity");b.TryActivateBossRosterSkill(b.RunId,5,u.EntityId,"absurdity");b.Advance(4);Assert.That(camera.Shield,Is.GreaterThan(0));Assert.That(b.TryDamageBossRosterObject(b.RunId,camera.Id,100000),Is.True);Assert.That(camera.Alive,Is.True);Assert.That(camera.Shield,Is.Zero);Assert.That(b.TryDamageBossRosterObject(b.RunId,camera.Id,1),Is.False);}
        [Test]public void EnvironmentalDamageIsNeverCreditedToTheNextDefender()
        {var b=Battle("B22",out var u);b.TryDamageUnit(u.EntityId,20+b.UnitCombat(u).UnitArmor,CombatDamageType.Physical);float before=u.Health;b.TryDamageUnit(u.EntityId,40+b.UnitCombat(u).UnitArmor,CombatDamageType.Physical,sourceDefender:b.Defender);float loss=before-u.Health;var method=typeof(ManualBattle).GetMethod("BossRosterRecordDefenderHit",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);method.Invoke(b,new object[]{b.Defender,u});Assert.That(b.BossRoster(u).DamageByDefender[b.Defender.EntityId],Is.EqualTo(loss).Within(.001));}
        [TestCase("B01","c4")][TestCase("B04","dash")][TestCase("B23","gospel")][TestCase("B25","judgement")]
        public void TargetedSkillsRejectEmptyStartWithoutSpOrUseLoss(string task,string skill)
        {var b=Battle(task,out var u);Charge(b,u,skill);foreach(var d in b.Defenders)d.Health=0;float sp=b.BossRoster(u).SP[skill];Assert.That(b.TryActivateBossRosterSkill(b.RunId,13,u.EntityId,skill),Is.EqualTo(SkillFailure.NoTarget));Assert.That(b.BossRoster(u).SP[skill],Is.EqualTo(sp));Assert.That(u.SkillsUsed,Is.Zero);Assert.That(b.SkillCasts,Is.Zero);}
        [Test]public void PureBuffCanOpenWithoutAnEnemyAndLaunchedTargetLossKeepsTheActionLock()
        {var b=Battle("B26",out var u);Charge(b,u,"balance");foreach(var d in b.Defenders)d.Health=0;Assert.That(b.TryActivateBossRosterSkill(b.RunId,14,u.EntityId,"balance"),Is.EqualTo(SkillFailure.None));var attack=Battle("B01",out var w);Charge(attack,w,"c4");Assert.That(attack.TryActivateBossRosterSkill(attack.RunId,15,w.EntityId,"c4"),Is.EqualTo(SkillFailure.None));attack.Defender.Health=0;Assert.That(attack.BossRosterMoveLock(w),Is.True);attack.SetPaused(true);double until=attack.BossRoster(w).LockedUntil;attack.Advance(100);Assert.That(attack.BossRoster(w).LockedUntil,Is.EqualTo(until));}
        [Test]public void OldCoreIdsAreNotReplacedAndBossIdentityDoesNotGrantBlanketControlImmunity()
        {foreach(string id in new[]{"CARD_M25","CARD_M32","CARD_TALULAH_TRIAL","CARD_M20","CARD_M14","CARD_M28","CARD_WISADEL_APRIL"})Assert.That(BossRosterRules.Supports(id),Is.False);foreach(string task in new[]{"B01","B03"}){var b=Battle(task,out var u);Assert.That(b.BossRosterControlImmune(u),Is.False);Assert.That(b.UnitInvulnerable(u),Is.False);}var merchant=Battle("B10",out var m);Assert.That(merchant.BossRosterInvulnerable(m),Is.True);Assert.That(merchant.BossRosterUnblockable(m),Is.True);}
        [Test]public void SuiLeavesSourceArenaWaitingAfterAllDefendersFallAndCanCompleteItsRoute()
        {var b=Battle("B21",out var u);b.Advance(26);Assert.That(b.BossRoster(u).Present,Is.False);foreach(var d in b.Defenders)d.Health=0;double before=u.Motion.DistanceTravelled;b.Advance(.3f);Assert.That(b.BossRoster(u).Present,Is.True);Assert.That(u.Motion.DistanceTravelled,Is.GreaterThan(before));Assert.That(b.BossRosterFrame(u,out var raw,out var age,out var loop),Is.True);Assert.That(raw,Is.EqualTo("Skill_Idle_A"));for(int i=0;i<200&&u.Active;i++)b.Advance(1);Assert.That(u.Resolution,Is.EqualTo(UnitResolution.Breached));Assert.That(b.BossRosterEvents.Count(e=>e.SkillKey=="exit"),Is.EqualTo(1));}
        [Test]public void WitchEdictRemembersOnlyActuallyStunnedAlliesAcrossItsWindow()
        {
            var b=Battle("B11",out var ignored,begin:false);var profiles=new[]{"CARD_M02","CARD_M03","CARD_M04"}.Select(id=>new BasicRosterProfile(new ManualBattleSettings(id,id,100,5,1,1,.1f,2000,.01f,1,30,1,10000),b.CombatSettings,true));b.ConfigureCardLoadout(profiles);b.Begin();var owner=b.FindUnit(b.TryDeploy(b.RunId,1,b.Entry).EntityId);owner.Motion.Advance(10);var allies=new DeployedUnitState[3];for(int i=0;i<3;i++){var receipt=b.TryDeployRole(b.RunId,2+i,b.Entry,new[]{"CARD_M02","CARD_M03","CARD_M04"}[i]);Assert.That(receipt.Success,Is.True);allies[i]=b.FindUnit(receipt.EntityId);allies[i].Motion.ApproachDistance(4+i,10000);allies[i].NextAttackTime=1000;}owner.NextAttackTime=1000;var s=b.BossRoster(owner);s.Phase=2;allies[0].PillarStunnedUntil=b.Clock+2;allies[2].FearUntil=b.Clock+8;Charge(b,owner,"edict");float guard=b.Defender.Health;Assert.That(b.TryActivateBossRosterSkill(b.RunId,20,owner.EntityId,"edict"),Is.EqualTo(SkillFailure.None));b.Advance(2);allies[1].ShackleStunnedUntil=b.Clock+.3;b.Advance(6);Assert.That(allies[0].Health,Is.LessThan(2000));Assert.That(allies[1].Health,Is.LessThan(2000));Assert.That(allies[2].Health,Is.EqualTo(2000));Assert.That(b.Defender.Health,Is.EqualTo(guard));var hits=b.BossRosterEvents.Where(e=>e.SkillKey=="edict"&&e.Kind=="Impact"&&e.Applied).Select(e=>e.TargetId).ToArray();Assert.That(hits,Is.EquivalentTo(new[]{allies[0].EntityId,allies[1].EntityId}));
        }
        static BossRosterObject AwaitAttachedHound(ManualBattle b)
        {for(int i=0;i<500;i++){var found=b.BossRosterObjects.FirstOrDefault(o=>o.Kind=="hound"&&o.Alive&&o.Animation=="Skill_Loop");if(found!=null)return found;b.Advance(.05f);}Assert.Fail("A legal target must receive the source first jump after 15 seconds and any current full attack.");return null;}
        [Test]public void HoundsUseMeleeContactThenTheirRealPeriodicAttachedAbility()
        {
            var b=Battle("B14",out var owner);b.TryDamageUnit(owner.EntityId,owner.MaxHealth*3,CombatDamageType.Physical);b.Advance(4);Assert.That(b.BossRosterEvents.Any(e=>e.Kind=="Impact"&&e.SkillKey=="hound"&&e.Applied),Is.True);Assert.That(b.BossRosterEvents.Any(e=>e.Kind=="ProjectileSpawn"&&e.SkillKey=="hound"),Is.False);var hound=AwaitAttachedHound(b);long activation=hound.ActivationId;var target=b.FindDefender(hound.TargetId);Assert.That(hound.Position,Is.EqualTo(target.Position));Assert.That(b.TryControlBossRosterObject(b.RunId,hound.Id,5),Is.False,"The original Jump graph is control immune.");b.SetPaused(true);double clock=b.Clock;int count=b.BossRosterEvents.Count;b.Advance(20);Assert.That(b.Clock,Is.EqualTo(clock));Assert.That(b.BossRosterEvents.Count,Is.EqualTo(count));b.SetPaused(false);b.Advance(3.1f);var hits=b.BossRosterEvents.Where(e=>e.ActivationId==activation&&e.Kind=="Impact"&&e.SkillKey=="attachBite").ToArray();Assert.That(hits.Length,Is.EqualTo(3));Assert.That(hits.Select(e=>e.HitIndex),Is.EqualTo(new[]{0,1,2}));Assert.That(hits.All(e=>e.Applied),Is.True);Assert.That(hits[1].At-hits[0].At,Is.EqualTo(1).Within(.051));Assert.That(b.BossRosterDefenderHitChance(target,CombatDamageType.Physical),Is.EqualTo(.2f));Assert.That(b.BossRosterDefenderHitChance(target,CombatDamageType.Arts),Is.EqualTo(.2f));b.Advance(8);Assert.That(b.BossRosterEvents.Any(e=>e.Kind=="SkillEnd"&&e.SkillKey=="attachBite"&&e.ActivationId==activation),Is.True);
        }
        [Test]public void AttachedHoundDeathCancelsFurtherBitesAndDoesNotTeleportItsCorpse()
        {var b=Battle("B14",out var owner);b.TryDamageUnit(owner.EntityId,owner.MaxHealth*3,CombatDamageType.Physical);var hound=AwaitAttachedHound(b);long activation=hound.ActivationId;Vector3 position=hound.Position;int count=b.BossRosterEvents.Count(e=>e.Kind=="Impact"&&e.SkillKey=="attachBite"&&e.ActivationId==activation);Assert.That(b.TryDamageBossRosterObject(b.RunId,hound.Id,hound.MaxHealth*2),Is.True);b.Advance(2);Assert.That(hound.Position,Is.EqualTo(position));Assert.That(b.BossRosterEvents.Count(e=>e.Kind=="Impact"&&e.SkillKey=="attachBite"&&e.ActivationId==activation),Is.EqualTo(count));Assert.That(b.BossRosterEvents.Any(e=>e.Kind=="SkillEnd"&&e.ActivationId==activation&&e.Cancelled),Is.True);}
        [Test]public void DeadAttachmentTargetReleasesTheHoundAndControlOnlyAppliesOutsideJump()
        {var b=Battle("B14",out var owner);b.TryDamageUnit(owner.EntityId,owner.MaxHealth*3,CombatDamageType.Physical);var hound=AwaitAttachedHound(b);var target=b.FindDefender(hound.TargetId);long activation=hound.ActivationId;target.Health=0;b.Advance(.5f);Assert.That(b.BossRosterEvents.Any(e=>e.Kind=="SkillEnd"&&e.SkillKey=="attachBite"&&e.ActivationId==activation),Is.True);Assert.That(hound.Animation,Is.Not.EqualTo("Skill_Loop"));Assert.That(b.TryControlBossRosterObject(b.RunId,hound.Id,2),Is.True);b.SetPaused(true);double until=hound.ControlledUntil;b.Advance(10);Assert.That(hound.ControlledUntil,Is.EqualTo(until));b.Restart();Assert.That(b.BossRosterObjects,Is.Empty);Assert.That(b.BossRosterRampage(target).Accumulated,Is.Zero);}
        [Test]public void RealHoundHitsCauseDistinctRampageThatEscalatesOnActualDefenderAbilities()
        {var b=Battle("B14",out var owner,guardsAttack:true);b.TryDamageUnit(owner.EntityId,owner.MaxHealth*3,CombatDamageType.Physical);b.Advance(13);var info=b.BossRosterRampage(b.Defender);Assert.That(info.Bursts,Is.EqualTo(1));Assert.That(info.Until,Is.GreaterThan(b.Clock));Assert.That(info.TickDamage,Is.GreaterThan(10));Assert.That(b.BossRosterDefenderAttackSpeedBonus(b.Defender),Is.EqualTo(.5f));Assert.That(b.BossRosterEvents.Any(e=>e.Kind=="Impact"&&e.SkillKey=="rampage"&&e.Applied),Is.True);b.SetPaused(true);b.Advance(30);Assert.That(b.BossRosterRampage(b.Defender).Until,Is.EqualTo(info.Until));b.SetPaused(false);b.Advance(16);Assert.That(b.BossRosterEvents.Any(e=>e.Kind=="StateEnd"&&e.SkillKey=="rampage"),Is.True);Assert.That(b.BossRosterRampage(b.Defender).TickDamage,Is.LessThanOrEqualTo(60));}
        [Test]public void ExplicitElementImmunityPreventsRampageWithoutGrantingUniversalStatusImmunity()
        {var b=Battle("B14",out var ignored,begin:false);b.ConfigureBossRosterRampageImmunity(new[]{"near"});b.Begin();var owner=b.FindUnit(b.TryDeploy(b.RunId,1,b.Entry).EntityId);b.TryDamageUnit(owner.EntityId,owner.MaxHealth*3,CombatDamageType.Physical);b.Advance(17);Assert.That(b.BossRosterRampage(b.Defender).Immune,Is.True);Assert.That(b.BossRosterRampage(b.Defender).Accumulated,Is.Zero);Assert.That(b.BossRosterRampage(b.Defender).Bursts,Is.Zero);Assert.That(b.BossRosterDefenderHitChance(b.Defender,CombatDamageType.Arts),Is.EqualTo(.2f));}
    }
